  1143  /* Like yyerror() but takes a printf-style format string. */
  1144  void
  1145  sudoerserrorf(const char *fmt, ...)
  1146  {
  1147      debug_decl(sudoerserrorf, SUDOERS_DEBUG_PARSER);
  1148
  1149      /* The lexer displays more detailed messages for ERROR tokens. */
  1150      if (sudoerschar == ERROR)
  1151          debug_return;
  1152
  1153      /* Save the line the first error occurred on. */
  1154      if (errorlineno == -1) {
  1155          errorlineno = this_lineno;
  1156          rcstr_delref(errorfile);
  1157          errorfile = rcstr_addref(sudoers);
  1158      }
  1159      if (sudoers_warnings && fmt != NULL) {
  1160          LEXTRACE("<*> ");
  1161  #ifndef TRACELEXER
  1162          if (trace_print == NULL || trace_print == sudoers_trace_print) {
  1163              char *s, *tofree = NULL;
  1164              int oldlocale;
  1165              va_list ap;
  1166
  1167              /* Warnings are displayed in the user's locale. */
  1168              sudoers_setlocale(SUDOERS_LOCALE_USER, &oldlocale);
  1169              va_start(ap, fmt);
  1170              if (strcmp(fmt, "%s") == 0) {
  1171                  /* Optimize common case, a single string. */
  1172                  s = _(va_arg(ap, char *));
  1173              } else {
  1174                  if (vasprintf(&s, fmt, ap) != -1)
  1175                      tofree = s;
  1176                  else
  1177                      s = _("syntax error");
  1178              }
  1179              sudo_printf(SUDO_CONV_ERROR_MSG, _("%s:%d:%d: %s\n"), sudoers,
  1180                  this_lineno, (int)sudolinebuf.toke_start + 1, s);
  1181              free(tofree);
  1182              va_end(ap);
  1183              sudoers_setlocale(oldlocale, NULL);
  1184
  1185              /* Display the offending line and token if possible. */
  1186              if (sudolinebuf.len != 0) {
  1187                  char tildes[128];
  1188                  size_t tlen = 0;
  1189
  1190                  sudo_printf(SUDO_CONV_ERROR_MSG, "%s%s", sudolinebuf.buf,
  1191                      sudolinebuf.buf[sudolinebuf.len - 1] == '\n' ? "" : "\n");
  1192                  if (sudolinebuf.toke_end > sudolinebuf.toke_start) {
  1193                      tlen = sudolinebuf.toke_end - sudolinebuf.toke_start - 1;
  1194                      if (tlen >= sizeof(tildes))
  1195                          tlen = sizeof(tildes) - 1;
  1196                      memset(tildes, '~', tlen);
  1197                  }
  1198                  tildes[tlen] = '\0';
  1199                  sudo_printf(SUDO_CONV_ERROR_MSG, "%*s^%s\n",
  1200                      (int)sudolinebuf.toke_start, "", tildes);
  1201              }
  1202          }
  1203  #endif
  1204      }
  1205      parse_error = true;
  1206      debug_return;
  1207  }
